<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Conway's Game of Life</title>
<style>
  html,body{margin:0;height:100%;background:#0b0f14;color:#e6edf3;font-family:system-ui,Segoe UI,Roboto,Helvetica,Arial,sans-serif}
  body{display:flex;align-items:center;justify-content:center}
  #container{text-align:center}
  h1{margin:0 0 12px;font-weight:800;letter-spacing:.5px}
  #controls{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin:14px 0}
  button{background:#1f2937;color:#e6edf3;border:1px solid #334155;padding:10px 16px;border-radius:12px;cursor:pointer;font-weight:700;transition:.15s}
  button:hover{background:#273449;transform:translateY(-1px)}
  button:active{transform:translateY(0)}
  #life{border:2px solid #334155;border-radius:14px;box-shadow:0 0 40px rgba(0,255,200,.12);background:#0b0f14;cursor:crosshair}
</style>
</head>
<body>
<div id="container">
  <h1>Game of Life</h1>
  <div id="controls">
    <button id="step">Step</button>
    <button id="play">Play</button>
    <button id="random">Random</button>
    <button id="clear">Clear</button>
  </div>
  <canvas id="life" width="400" height="400"></canvas>
</div>
<script>
(() => {
  const w = 80, h = 80;
  const cellSize = 5;
  const canvas = document.getElementById('life');
  const ctx = canvas.getContext('2d');
  canvas.width = w * cellSize;
  canvas.height = h * cellSize;

  let grid = Array.from({length:h},()=>Array(w).fill(0));

  function draw(){
    ctx.fillStyle = '#0b0f14';
    ctx.fillRect(0,0,canvas.width,canvas.height);
    ctx.fillStyle = '#7ee787';
    for(let y=0;y<h;y++){
      for(let x=0;x<w;x++){
        if(grid[y][x]){
          ctx.fillRect(x*cellSize+0.5, y*cellSize+0.5, cellSize-1, cellSize-1);
        }
      }
    }
  }

  function step(){
    const next = Array.from({length:h},()=>Array(w).fill(0));
    for(let y=0;y<h;y++){
      for(let x=0;x<w;x++){
        let n=0;
        for(let dy=-1;dy<=1;dy++){
          for(let dx=-1;dx<=1;dx++){
            if(dx===0 && dy===0) continue;
            const nx=x+dx, ny=y+dy;
            if(nx>=0 && nx<w && ny>=0 && ny<h) n+=grid[ny][nx];
          }
        }
        if(grid[y][x]){
          next[y][x] = (n===2 || n===3) ? 1 : 0;
        }else{
          next[y][x] = (n===3) ? 1 : 0;
        }
      }
    }
    grid = next;
    draw();
  }

  function clearGrid(){
    for(let y=0;y<h;y++) for(let x=0;x<w;x++) grid[y][x]=0;
    draw();
  }

  function randomize(){
    for(let y=0;y<h;y++) for(let x=0;x<w;x++) grid[y][x]= Math.random()<0.3 ? 1 : 0;
    draw();
  }

  function cellFromEvent(e){
    const rect = canvas.getBoundingClientRect();
    const sx = w / rect.width;
    const sy = h / rect.height;
    const x = Math.floor((e.clientX - rect.left) * sx);
    const y = Math.floor((e.clientY - rect.top) * sy);
    return {x,y};
  }

  let drawing=false;
  canvas.addEventListener('mousedown', e=>{drawing=true; toggle(e);});
  canvas.addEventListener('mousemove', e=>{if(drawing) toggle(e);});
  window.addEventListener('mouseup', ()=>drawing=false);
  function toggle(e){
    const {x,y}=cellFromEvent(e);
    if(x>=0 && x<w && y>=0 && y<h){
      grid[y][x] ^= 1;
      draw();
    }
  }

  document.getElementById('step').onclick = step;
  document.getElementById('clear').onclick = clearGrid;
  document.getElementById('random').onclick = randomize;

  let playing=false, timer=null;
  const playBtn=document.getElementById('play');
  playBtn.onclick=()=>{
    playing=!playing;
    if(playing){
      playBtn.textContent='Pause';
      timer=setInterval(step,120);
    }else{
      playBtn.textContent='Play';
      clearInterval(timer);
    }
  };

  window.life = {
    w, h,
    get(x,y){ if(x<0||y<0||x>=w||y>=h) return 0; return grid[y][x]; },
    set(x,y,v){ if(x<0||y<0||x>=w||y>=h) return; grid[y][x]= v?1:0; draw(); },
    step,
    clear: clearGrid
  };

  draw();
})();
</script>
</body>
</html>
